139	    \State $S(h) \gets I(h) \times (1 - F(h))^\alpha$
140	\EndFor
141	\State Sort $\mathcal{H}$ by $S(h)$ ascending
142	\State $\mathcal{P} \gets \emptyset$
143	\For{each $h$ in sorted $\mathcal{H}$}
144	    \If{layer($h$) retains $< \tau$ fraction after adding $h$ to $\mathcal{P}$}
145	        \State \textbf{continue}
146	    \EndIf
147	    \State $\mathcal{P} \gets \mathcal{P} \cup \{h\}$
148	    \If{$\sum_{h' \in \mathcal{P}} \text{params}(h') \ge s \cdot |\theta|$}
149	        \State \textbf{break}
150	    \EndIf
151	\EndFor
152	\State $\mathcal{M}_\text{pruned} \gets \text{Remove}(\mathcal{M}, \mathcal{P})$
153	\Statex \textit{\% Stage 3: Two-Stage Recovery}
154	\State $\mathcal{M}_\text{warm} \gets \text{SFT}(\mathcal{M}_\text{pruned}, \mathcal{D}_\text{sft})$ \hfill $\triangleright$ restore EOS \& format
155	\State $\mathcal{M}' \gets \text{GRPO}(\mathcal{M}_\text{warm}, \mathcal{D}_\text{rlvr})$ \hfill $\triangleright$ restore reasoning
